// createPhysicsBody puzzle
function createPhysicsBody(type, objSelector, shape, mass) {

    if (!window.Ammo || !_pGlob.world)
        return;

    var objNames = PzLib.retrieveObjectNames(objSelector);

    objNames.forEach(function(objName) {
        if (!objName)
            return;

        var obj = PzLib.getObjectByName(objName);
        if (!obj)
            return;

        PzLib.findAndRemovePhysicsBody(obj);

        switch (shape) {
        case 'BOX':
        case 'CAPSULE':
        case 'CONE':
        case 'CYLINDER':

            var box = new v3d.Box3();

            obj.resolveMultiMaterial().forEach(function(objR) {
                if (objR.geometry) {
                    if (objR.geometry.boundingBox == null)
                        objR.geometry.computeBoundingBox();

                    box.union(objR.geometry.boundingBox);
                }
            });

            var size = box.getSize(new v3d.Vector3());

            // do not allow empty-sized shapes
            size.x = size.x || 0.5;
            size.y = size.y || 0.5;
            size.z = size.z || 0.5;

            if (shape == 'BOX') {
                var geometry = new Ammo.btBoxShape(new Ammo.btVector3(
                        size.x * 0.5, size.y * 0.5, size.z * 0.5));
            } else if (shape == 'CAPSULE') {
                var radius = Math.max(size.x, size.z) * 0.5;
                var height = size.y - 2 * radius;
                var geometry = new Ammo.btCapsuleShape(radius, height);
            } else if (shape == 'CONE') {
                var radius = Math.max(size.x, size.z) * 0.5;
                var height = size.y;
                var geometry = new Ammo.btConeShape(radius, height);
            } else {
                var geometry = new Ammo.btCylinderShape(new Ammo.btVector3(
                        size.x * 0.5, size.y * 0.5, size.z * 0.5));
            }

            break;
        case 'SPHERE':

            var sphere = new v3d.Sphere();

            obj.resolveMultiMaterial().forEach(function(objR) {
                if (objR.geometry) {
                    // NOTE: by default spheres are based on boundings
                    // so always recalculate them here
                    objR.geometry.computeBoundingSphere();

                    if (sphere.isEmpty()) {
                        sphere.copy(objR.geometry.boundingSphere);
                    } else {
                        sphere.union(objR.geometry.boundingSphere);
                    }
                }
            });

            if (sphere.isEmpty()) {
                sphere.radius = 0.5;
            }

            var geometry = new Ammo.btSphereShape(sphere.isEmpty() ? 0.5 : sphere.radius);

            break;
        case 'MESH':

            var objsR = obj.resolveMultiMaterial();

            if (!objsR[0].geometry || !objsR[0].isMesh) {
                console.error('create rigid body puzzle: Incorrect mesh object');
                var geometry = new Ammo.btEmptyShape();
                break;
            }

            // allow complex triangle shapes for KINEMATIC objects
            if (type == 'DYNAMIC' || type == 'GHOST') {

                var geometry = new Ammo.btConvexHullShape();

                objsR.forEach(function(objR) {
                    var positions = objR.geometry.attributes.position.array;

                    for (var i = 0; i < positions.length; i+=3) {
                        var x = positions[i];
                        var y = positions[i+1];
                        var z = positions[i+2];

                        var v = new Ammo.btVector3(x, y, z);

                        geometry.addPoint(v);

                        Ammo.destroy(v);
                    }
                });

            } else {

                var triIdxVertArray = new Ammo.btTriangleMesh();

                objsR.forEach(function(objR) {
                    var positions = objR.geometry.attributes.position.array;
                    var indices = objR.geometry.index.array;

                    for (var i = 0; i < indices.length; i+=3) {

                        var i1 = indices[i];
                        var i2 = indices[i+1];
                        var i3 = indices[i+2];

                        var v1 = new Ammo.btVector3(positions[3*i1], positions[3*i1+1], positions[3*i1+2]);
                        var v2 = new Ammo.btVector3(positions[3*i2], positions[3*i2+1], positions[3*i2+2]);
                        var v3 = new Ammo.btVector3(positions[3*i3], positions[3*i3+1], positions[3*i3+2]);

                        triIdxVertArray.addTriangle(v1, v2, v3, false);

                        Ammo.destroy(v1);
                        Ammo.destroy(v2);
                        Ammo.destroy(v3);
                    }
                });

                var geometry = new Ammo.btBvhTriangleMeshShape(triIdxVertArray, true);

            }

            break;
        case 'EMPTY':
            var geometry = new Ammo.btEmptyShape();
            break;
        }

        var pos = obj.getWorldPosition(_pGlob.vec3Tmp);
        var quat = obj.getWorldQuaternion(_pGlob.quatTmp);

        var transform = new Ammo.btTransform();
        transform.setIdentity();
        transform.setOrigin(new Ammo.btVector3(pos.x, pos.y, pos.z));
        transform.setRotation(new Ammo.btQuaternion(quat.x, quat.y, quat.z, quat.w));
        var motionState = new Ammo.btDefaultMotionState(transform);

        if (type == 'STATIC' || type == 'KINEMATIC' || type == 'GHOST')
            var bodyMass = 0;
        else
            var bodyMass = mass;

        var localInertia = new Ammo.btVector3(0, 0, 0);
        geometry.calculateLocalInertia(bodyMass, localInertia);

        var rbInfo = new Ammo.btRigidBodyConstructionInfo(bodyMass, motionState, geometry, localInertia);
        var body = new Ammo.btRigidBody(rbInfo);

        // CF_STATIC_OBJECT is set automatically

        if (type == 'KINEMATIC' || type == 'GHOST') {
            body.setCollisionFlags(body.getCollisionFlags() | CF_KINEMATIC_OBJECT);
            body.setActivationState(DISABLE_DEACTIVATION);
        }

        if (type == 'GHOST') {

            body.setCollisionFlags(body.getCollisionFlags() | CF_NO_CONTACT_RESPONSE);
            _pGlob.world.addRigidBody(body, SensorTrigger, AllFilter);

        } else {

            _pGlob.world.addRigidBody(body);

        }


        //body.setDamping(0.1, 0.1);

        _pGlob.syncList.push({
            obj: obj,
            body: body,
            type: type,
            simulated: true,
            mass: mass
        });

        // external physics interface
        if (PL) {
            PL.physics.bodies[objName] = body;
        }
    });


}

// detectCollision puzzle
function detectCollision(objSelectorA, objSelectorB, collideCb, noCollideCb) {
    if (!window.Ammo || !_pGlob.world)
        return;

    var objNamesA = PzLib.retrieveObjectNames(objSelectorA);
    var objNamesB = PzLib.retrieveObjectNames(objSelectorB);

    var objA = PzLib.getObjectByName(objNamesA[0]);
    var execInstanceID = v3d.MathUtils.generateUUID();

    for (var i = 0; i < objNamesB.length; i++) {
        var objB = PzLib.getObjectByName(objNamesB[i]);

        var bodyA = null;
        var bodyB = null;

        for (var j = 0; j < _pGlob.syncList.length; j++) {
            var syncData = _pGlob.syncList[j];

            if (syncData.obj == objA)
                bodyA = syncData.body;

            if (syncData.obj == objB)
                bodyB = syncData.body;
        }

        if (objA && objB && bodyA && bodyB) {
            _pGlob.collisionData.push({
                objA: objA,
                objB: objB,
                bodyA: bodyA,
                bodyB: bodyB,
                collideCb: collideCb,
                noCollideCb: noCollideCb,
                collideFlag: true,
                execInstanceID: execInstanceID
            });
        }
    }

}

function getObjectsFromCollect(obj, type, nameFilterType, nameFilter, useID, out) {
    if (!PzLib.isObjectWorthProcessing(obj)) {
        return;
    }

    let doCollect = true;

    if (nameFilter) {
        switch (nameFilterType) {
        case 'NAME_EQUAL':
            if (obj.name != nameFilter)
                doCollect = false;
            break;
        case 'NAME_START':
            if (!obj.name.startsWith(nameFilter))
                doCollect = false;
            break;
        case 'NAME_END':
            if (!obj.name.endsWith(nameFilter))
                doCollect = false;
            break;
        case 'NAME_INCLUDE':
            if (!obj.name.includes(nameFilter))
                doCollect = false;
            break;
        }
    }

    if (doCollect) {
        const nameOrID = useID ? obj.uuid : obj.name;

        switch (type) {
        case 'ALL':
        case 'FIRST':
            if (out.indexOf(nameOrID) < 0)
                out.push(nameOrID);
            break;
        case 'ANNOTATION':
            if (obj.isAnnotation && out.indexOf(nameOrID) < 0)
                out.push(nameOrID);
            break;
        case 'BONE':
            if (obj.isBone && out.indexOf(nameOrID) < 0)
                out.push(nameOrID);
            break;
        case 'CAMERA':
            if (obj.isCamera && out.indexOf(nameOrID) < 0)
                out.push(nameOrID);
            break;
        case 'EMPTY':
            if (!obj.isAnnotationControl && !obj.isBone && !obj.isCamera &&
                    !obj.isGroup && !obj.isLine && !obj.isLOD && !obj.isLight &&
                    !PzLib.isMeshObject(obj) && !obj.isPoints && !obj.isScene &&
                    !obj.isSprite && out.indexOf(nameOrID) < 0)
                out.push(nameOrID);
            break;
        case 'LIGHT':
            if (obj.isLight && out.indexOf(nameOrID) < 0)
                out.push(nameOrID);
            break;
        case 'MESH':
            if (PzLib.isMeshObject(obj) && out.indexOf(nameOrID) < 0)
                out.push(nameOrID);
            break;
        default:
            console.error('get objects from puzzle: Unknown object type: ' + type);
            break;
        }
    }

    for (let i = 0; i < obj.children.length; i++) {
        const child = obj.children[i];
        getObjectsFromCollect(child, type, nameFilterType, nameFilter, useID, out);
    }
}

// getObjectsFrom puzzle
function getObjectsFrom(objSelector, type, nameFilterType, nameFilter, useID) {
    const out = [];

    const objNames = PzLib.retrieveObjectNames(objSelector);

    for (let i = 0; i < objNames.length; i++) {
        const objName = objNames[i]
        if (!objName)
            continue;

        const obj = PzLib.getObjectByName(objName);
        if (!obj)
            continue;

        getObjectsFromCollect(obj, type, nameFilterType, nameFilter, useID, out);
    }

    return (type == 'FIRST') ? out[0] : out;
}

function setMorphFactor(objSelector, targetName, factor) {
    if (!targetName)
        return;

    const objNames = PzLib.retrieveObjectNames(objSelector);

    for (let i = 0; i < objNames.length; i++) {
        const objName = objNames[i]
        if (!objName)
            continue;
        let obj = PzLib.getObjectByName(objName);
        if (!obj)
            continue;

        obj.resolveMultiMaterial().forEach(function(objR) {
            if (objR.morphTargetDictionary && targetName in objR.morphTargetDictionary) {
                const idx = objR.morphTargetDictionary[targetName];
                objR.morphTargetInfluences[idx] = Number(factor);
            }
        });

        obj.resolveMultiMaterial().forEach(function(objR) {
            objR.getAuxClippingMeshes().forEach(function(objC) {
                if (objC.morphTargetDictionary && targetName in objC.morphTargetDictionary) {
                    const idx = objC.morphTargetDictionary[targetName];
                    objC.morphTargetInfluences[idx] = Number(factor);
                }
            });
        });
    }
}

